const TERMINAL_NAMES: readonly string[] = ["EOF","IDENT","INTEGER","\"fn\"","\"=\"","\";\"","\"let\"","\"in\"","\"if\"","\"then\"","\"else\"","\"likely\"","\"unlikely\"","\"fun\"","\"->\"","\"lazy\"","\"force\"","\"==\"","\"!=\"","\"<\"","\"<=\"","\">\"","\">=\"","\"+\"","\"-\"","\"*\"","\"/\"","\"(\"","\")\"","\",\"","\"tick\""];
